//! What the lowering knows about built-ins: the stdlib families, the FILE and
//! READ contracts, the options-map contracts, the AI tiers. The data
//! (`vocabulary/data.rs`) is generated from the TypeScript declarations
//! (expression/stdlib.ts, shared/expression/types.ts) by
//! parser/expression/__test__/lowering_vocabulary.unit.test.ts, which pins it,
//! so the two cannot drift. It is Rust rather than JSON so that reading it
//! costs the WASM nothing. Only a contract's cross-option rule is code
//! (`call_shape::agree`).

/// The data, generated by the pin's test (`UPDATE_LOWERING_VOCABULARY=1`).
#[rustfmt::skip]
mod data;

pub struct Vocabulary {
    pub ai_tiers: &'static [&'static str],
    pub file: FileContract,
    pub read: ReadContract,
    pub options: &'static [OptionsContract],
    pub families: &'static [Family],
}

pub struct FileContract {
    pub fn_: &'static str,
    pub signature: &'static str,
    pub artifact_types: &'static [&'static str],
}

pub struct ReadContract {
    pub fn_: &'static str,
    pub signature: &'static str,
}

pub struct OptionsContract {
    pub fn_: &'static str,
    pub signature: &'static str,
    pub arity: usize,
    pub index: usize,
    pub options: &'static [OptionSpec],
    pub exactly_one: &'static [ExactlyOne],
    /// The name of the cross-option rule `call_shape::agree` carries.
    pub agree: Option<&'static str>,
}

pub struct OptionSpec {
    pub key: &'static str,
    pub type_: OptionType,
    pub required: bool,
    pub summary: &'static str,
    pub values: Option<&'static [&'static str]>,
    /// In declaration order; looked up by key.
    pub unavailable: Option<&'static [(&'static str, &'static str)]>,
}

/// `Text` is the checker's to read; the lowering settles `Literal` only.
#[allow(dead_code)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OptionType {
    Number,
    Text,
    Literal,
}

pub struct ExactlyOne {
    pub keys: &'static [&'static str],
    pub what: &'static str,
}

pub struct Family {
    pub namespace: &'static str,
    pub functions: &'static [FamilyFunction],
}

pub struct FamilyFunction {
    pub name: &'static str,
    pub id: &'static str,
    pub signature: &'static str,
    pub arity: Arity,
}

#[derive(Debug, Clone, Copy)]
pub struct Arity {
    pub min: usize,
    pub max: usize,
}

pub fn vocabulary() -> &'static Vocabulary {
    &data::VOCABULARY
}

impl Vocabulary {
    /// `stdlibFamily`: case-insensitive, as every function name is.
    pub fn family(&self, namespace: &str) -> Option<&Family> {
        let upper = namespace.to_uppercase();
        self.families.iter().find(|f| f.namespace == upper)
    }

    pub fn options_for(&self, fn_: &str) -> Option<&OptionsContract> {
        self.options.iter().find(|o| o.fn_ == fn_)
    }

    /// `listStdlibNamespaces`.
    pub fn namespaces(&self) -> Vec<&'static str> {
        self.families.iter().map(|f| f.namespace).collect()
    }
}

impl Family {
    /// `describeStdlibFamily`: `GET_NUMBER_FROM_FIGURE(figure), …`.
    pub fn describe(&self) -> String {
        self.functions
            .iter()
            .map(|f| {
                // `signature.slice(signature.indexOf('(') + 1)`: no `(` slices from 0.
                let after = f.signature.find('(').map_or(0, |i| i + 1);
                format!("{}({}", f.name, &f.signature[after..])
            })
            .collect::<Vec<_>>()
            .join(", ")
    }
}

impl OptionsContract {
    /// `describeBuiltinOptions`.
    pub fn describe(&self) -> String {
        let options = self
            .options
            .iter()
            .map(|o| format!("{}{} — {}", o.key, if o.required { " (required)" } else { "" }, o.summary))
            .collect::<Vec<_>>()
            .join("; ");
        let choices: String = self
            .exactly_one
            .iter()
            .map(|c| format!(" (exactly one of {})", quoted_list(c.keys, "'", " or ")))
            .collect();
        format!("{options}{choices}")
    }
}

/// `xs.map(x => `${q}${x}${q}`).join(sep)`.
pub fn quoted_list(items: &[&str], quote: &str, sep: &str) -> String {
    items.iter().map(|x| format!("{quote}{x}{quote}")).collect::<Vec<_>>().join(sep)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_data_reads_as_the_typescript_does() {
        let v = vocabulary();
        assert_eq!(v.ai_tiers, ["quick", "careful", "thorough"]);
        assert_eq!(v.family("currency").map(|f| f.namespace), Some("CURRENCY"));
        assert!(v.family("NOPE").is_none());
        assert_eq!(v.namespaces(), ["CURRENCY", "DATE", "DATETIME", "TEXT", "URL", "NUMBER"]);
        assert_eq!(
            v.family("TEXT").unwrap().describe(),
            "REGEX_EXTRACT(text, pattern, group?), SLUG(text), PAIRS(record, separator?), SERIALISE(value, format)"
        );
        assert_eq!(
            v.options_for("chunks").unwrap().describe(),
            "size — the most characters a piece may be; entities — the most records a piece is expected to yield, \
             cutting on whole lines; overlap — how many characters each piece repeats from the one before it (none by \
             default); unit — what size counts — \"chars\" (exactly one of 'size' or 'entities')"
        );
    }
}
